import{_ as t}from"./chunks/Audio.COine8Wh.js";import{_ as n}from"./chunks/Tags.BJ536pW3.js";import{c as r,o,j as i,G as a,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"To provide for reconciliation pursuant to title II of H. Con. Res. 14.","description":"","frontmatter":{"legisId":"2025-07-04-public-law-119-21","title":"To provide for reconciliation pursuant to title II of H. Con. Res. 14.","displayTitle":"H.R. 1, Public Law 119-21","lawNumber":"119-21","billNumber":"H.R. 1","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ21.xml","publishDate":"2025-07-04T00:00:00-05:00","industries":["government-operations","defense","immigration"],"agencies":["Department of Agriculture","Department of Defense","Department of the Treasury","Department of the Interior","Department of Energy","Department of Transportation","Department of Homeland Security","Department of Justice","Department of Education","Department of Health and Human Services","Department of Commerce","Office of Management and Budget","Internal Revenue Service","Consumer Financial Protection Bureau","Securities and Exchange Commission","Federal Reserve System","United States Coast Guard","Federal Communications Commission","Federal Aviation Administration","National Aeronautics and Space Administration","National Oceanic and Atmospheric Administration","Environmental Protection Agency","United States Customs and Border Protection","United States Immigration and Customs Enforcement","Federal Bureau of Prisons","United States Secret Service"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"To provide for reconciliation pursuant to title II of H. Con. Res. 14.\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-04-public-law-119-21\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"To provide for reconciliation pursuant to title II of H. Con. Res. 14.\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-04-public-law-119-21\\",\\"datePublished\\":\\"2025-07-04T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-04-public-law-119-21\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-07-04-public-law-119-21.md","filePath":"congress-bills/2025-07-04-public-law-119-21.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-07-04-public-law-119-21.md"},g=Object.assign(d,{setup(c){return(u,e)=>(o(),r("div",null,[e[0]||(e[0]=i("h1",{id:"to-provide-for-reconciliation-pursuant-to-title-ii-of-h-con-res-14",tabindex:"-1"},[l("To provide for reconciliation pursuant to title II of H. Con. Res. 14. "),i("a",{class:"header-anchor",href:"#to-provide-for-reconciliation-pursuant-to-title-ii-of-h-con-res-14","aria-label":'Permalink to "To provide for reconciliation pursuant to title II of H. Con. Res. 14."'},"​")],-1)),a(t),a(n,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Friday, July 4, 2025. Public Law 119-21, H.R. 1.</p><p><strong>Headline:</strong> H.R. 1 extends major tax cuts while reshaping healthcare, food aid, energy, education, immigration enforcement, defense, and federal spending.</p><p><strong>Why it matters:</strong> The law makes sweeping changes to taxes and safety-net eligibility, commits major funding to defense and border enforcement, expands fossil-fuel development, and cancels many climate and clean-energy programs. It also raises the federal debt limit by $5 trillion.</p><p><strong>What the law does:</strong></p><ul><li>Makes lower individual tax rates, the larger standard deduction, expanded business deductions, and several family and investment tax benefits permanent or more generous.</li><li>Creates temporary deductions for tips, overtime premiums, vehicle-loan interest, and seniors, while establishing tax-advantaged accounts for children.</li><li>Tightens Medicaid, health insurance tax credit, and SNAP eligibility and verification, adds Medicaid work requirements, shifts some SNAP costs to states, and creates a $50 billion rural health program.</li><li>Expands farm supports, crop insurance, agricultural disaster aid, defense procurement, military readiness, border barriers, immigration detention, removals, and immigration-related fees.</li><li>Requires additional federal oil, gas, coal, and timber leasing, lowers or limits some royalties, and funds petroleum reserves, critical minerals, nuclear power, and energy infrastructure.</li><li>Ends or accelerates many clean-energy tax credits, repeals the Greenhouse Gas Reduction Fund, and cancels unobligated climate, conservation, clean-transportation, and environmental funding.</li><li>Changes federal student loans, repayment plans, Pell Grants, and college accountability while creating Workforce Pell Grants for qualifying short-term training.</li><li>Funds Coast Guard assets, air traffic control modernization, NASA exploration, spectrum auctions, commercial space oversight, and federal law enforcement.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Taxpayers, families, seniors, tipped and overtime workers, small businesses, manufacturers, farmers, and charitable organizations.</li><li>Medicaid, Marketplace, SNAP, Medicare, student-aid, and unemployment-benefit recipients.</li><li>Service members, veterans’ families, immigrants, asylum seekers, border communities, federal employees, and law enforcement personnel.</li><li>Energy producers, clean-energy developers, colleges, healthcare providers, states, local governments, and rural communities.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Tax bills may change through permanent rate and deduction rules, temporary worker and senior deductions, a larger child tax credit, and revised state and local tax limits.</li><li>Access to Medicaid, SNAP, premium tax credits, student loans, and Pell Grants may require new eligibility checks, work documentation, repayment terms, or borrowing limits.</li><li>Vehicle and home clean-energy credits phase out sooner, while qualifying U.S.-assembled vehicle loans and some child, adoption, education, housing, and savings expenses receive new or expanded tax benefits.</li></ul><p><strong>Context:</strong> The law combines reconciliation changes across agriculture, defense, finance, energy, healthcare, education, transportation, immigration, environmental policy, and federal budgeting.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="title-i-committee-on-agriculture-nutrition-and-forestry" tabindex="-1">TITLE I, COMMITTEE ON AGRICULTURE, NUTRITION, AND FORESTRY <a class="header-anchor" href="#title-i-committee-on-agriculture-nutrition-and-forestry" aria-label="Permalink to &quot;TITLE I, COMMITTEE ON AGRICULTURE, NUTRITION, AND FORESTRY&quot;">​</a></h3><p>This title changes federal nutrition programs, farm commodity supports, disaster aid, crop insurance, conservation, research, trade promotion, and other rural programs. It revises SNAP benefit calculations and eligibility, shifts some SNAP costs to states, expands or extends many farm support programs, and directs new funding to selected agricultural initiatives. It also cancels certain unobligated forestry and conservation funds.</p><p><strong>Key takeaways:</strong></p><ul><li>SNAP benefits will continue to use the 2021 Thrifty Food Plan, with fixed household-size adjustments, annual inflation updates beginning October 1, 2025, and no cost increase from future market-basket reevaluations.</li><li>The title changes SNAP work-rule exemptions, narrows eligibility based on immigration status, excludes internet fees from shelter deductions, limits some utility allowances, reduces the federal share of state administrative costs, and requires states with higher payment error rates to pay part of benefit costs.</li><li>Farm commodity programs are extended through the 2031 crop year with higher reference prices, up to 30 million additional base acres, higher payment limits, revised income rules, and updated support for grains, cotton, sugar, dairy, and other commodities.</li><li>Agricultural disaster aid is expanded for livestock losses, unborn livestock, drought-affected grazing, farm-raised fish losses caused by birds, honeybee losses, and damaged trees.</li><li>Crop insurance support is increased through broader beginning-farmer benefits, higher coverage and premium subsidies, added payments to insurance providers, more compliance funding, and a poultry insurance pilot program.</li><li>The title funds conservation, agricultural exports, research, specialty crops, animal disease programs, and other rural initiatives while rescinding specified unobligated forestry and conservation balances.</li></ul><h3 id="title-ii-committee-on-armed-services" tabindex="-1">TITLE II, COMMITTEE ON ARMED SERVICES <a class="header-anchor" href="#title-ii-committee-on-armed-services" aria-label="Permalink to &quot;TITLE II, COMMITTEE ON ARMED SERVICES&quot;">​</a></h3><p>This title provides additional fiscal year 2025 defense funding, generally available through September 30, 2029, for military personnel, weapons, shipbuilding, missile defense, nuclear forces, readiness, technology, cybersecurity, and operations. It also invests in the defense industrial base and critical-mineral supply chains, expands certain military housing authorities, funds Indo-Pacific and border missions, and requires oversight and project-level military construction spending plans.</p><p><strong>Key takeaways:</strong></p><ul><li>The title funds military housing, health care, housing allowances, child care, education, bonuses, spouse licensing, and other quality-of-life programs for service members and their families.</li><li>It makes major investments in naval shipbuilding, military aircraft, munitions, missile defense, nuclear forces, unmanned systems, artificial intelligence, advanced communications, and other emerging technologies.</li><li>It supports defense production through expanded manufacturing capacity, workforce and supplier development, critical-mineral stockpiles and supply chains, and federal loans and loan guarantees.</li><li>It funds military readiness through depot and shipyard modernization, equipment repairs, spare parts, facility improvements, exercises, and operational support.</li><li>It provides resources for Indo-Pacific infrastructure and operations, military space and cyber capabilities, and Defense Department support for border, counter-drug, and migrant detention missions.</li><li>It temporarily expands investment and contracting authority for privatized military housing through September 30, 2029, while funding Defense Department oversight and requiring detailed military construction spending plans.</li></ul><h3 id="title-iii-committee-on-banking-housing-and-urban-affairs" tabindex="-1">TITLE III, COMMITTEE ON BANKING, HOUSING, AND URBAN AFFAIRS <a class="header-anchor" href="#title-iii-committee-on-banking-housing-and-urban-affairs" aria-label="Permalink to &quot;TITLE III, COMMITTEE ON BANKING, HOUSING, AND URBAN AFFAIRS&quot;">​</a></h3><p>This title reduces the funding cap for the Consumer Financial Protection Bureau, cancels unused funding for a multifamily housing retrofit program, and closes the Securities and Exchange Commission Reserve Fund. It also provides $1 billion for activities under the Defense Production Act.</p><p><strong>Key takeaways:</strong></p><ul><li>The Consumer Financial Protection Bureau’s funding cap is reduced from 12 percent to 6.5 percent of the Federal Reserve System’s inflation-adjusted operating expenses.</li><li>Unused funding for the Green and Resilient Retrofit Program for multifamily housing is canceled.</li><li>The Securities and Exchange Commission may temporarily use previously obligated Reserve Fund money for ongoing activities through September 30, 2025.</li><li>On October 1, 2025, all remaining Securities and Exchange Commission Reserve Fund balances are transferred to the Treasury’s general fund, and the account is closed.</li><li>The Securities and Exchange Commission’s whistleblower fund remains available without further appropriation or a fiscal-year limit to pay whistleblower awards.</li><li>The title provides $1 billion for Defense Production Act activities for fiscal year 2025, available through September 30, 2027.</li></ul><h3 id="title-iv-committee-on-commerce-science-and-transportation" tabindex="-1">TITLE IV, COMMITTEE ON COMMERCE, SCIENCE, AND TRANSPORTATION <a class="header-anchor" href="#title-iv-committee-on-commerce-science-and-transportation" aria-label="Permalink to &quot;TITLE IV, COMMITTEE ON COMMERCE, SCIENCE, AND TRANSPORTATION&quot;">​</a></h3><p>This title provides major funding for Coast Guard readiness, air traffic control modernization, and NASA exploration and infrastructure programs. It extends federal authority to auction spectrum, directs additional spectrum auctions and reallocations, and establishes fees for licensed commercial space launches and reentries. It also eliminates certain fuel-economy penalties, changes airport lease and travel-promotion payments, and rescinds several previously approved funding balances.</p><p><strong>Key takeaways:</strong></p><ul><li>The Coast Guard receives $24.59 billion for aircraft, cutters, icebreakers, shore facilities, maintenance, maritime awareness, and autonomous systems, with the funding available through September 2029.</li><li>The Federal Communications Commission’s general spectrum-auction authority is extended through September 2034, and federal agencies must identify and auction substantial additional spectrum for commercial wireless use while allowing the President to protect frequencies needed for national security.</li><li>The Federal Aviation Administration receives $12.52 billion for telecommunications and radar upgrades, runway and weather systems, air traffic facility construction and consolidation, remote towers, and controller training, with quarterly spending reports to Congress.</li><li>NASA receives nearly $10 billion for a Mars communications orbiter, the Gateway program, Artemis IV and V, Orion, the International Space Station, space-center infrastructure, and other specified projects.</li><li>Beginning in 2026, licensed commercial launches and reentries must pay payload-based user fees subject to annual caps, with 70 percent of collections available for commercial space licensing and related activities.</li><li>The title sets applicable corporate average fuel-economy civil penalties at zero, increases future Metropolitan Washington Airports lease payments, reduces annual transfers to the Travel Promotion Fund, and rescinds unobligated funds from specified NOAA, aviation-technology, and wireless supply-chain programs.</li></ul><h3 id="title-v-committee-on-energy-and-natural-resources" tabindex="-1">TITLE V, COMMITTEE ON ENERGY AND NATURAL RESOURCES <a class="header-anchor" href="#title-v-committee-on-energy-and-natural-resources" aria-label="Permalink to &quot;TITLE V, COMMITTEE ON ENERGY AND NATURAL RESOURCES&quot;">​</a></h3><p>This title expands federal oil, gas, coal, and timber leasing and production, including required lease sales onshore, offshore, and in Alaska. It lowers or limits several royalty rates, sets fees and revenue-sharing rules for energy development on federal land, and ends or withdraws funding for several earlier programs. It also funds the Strategic Petroleum Reserve, energy financing, artificial intelligence research, water infrastructure, and events marking the United States’ 250th anniversary.</p><p><strong>Key takeaways:</strong></p><ul><li>The Interior Department must resume quarterly onshore oil and gas lease sales, hold at least four annual sales in each of nine listed states, and offer qualifying nominated land under specified deadlines and terms.</li><li>The title requires at least 30 offshore oil and gas lease sales in the Gulf region through 2040, six Cook Inlet sales through 2032, four additional Coastal Plain sales, and at least five National Petroleum Reserve–Alaska sales.</li><li>It restores earlier oil and gas royalty rules, caps offshore royalties at 16⅔ percent, repeals the federal charge on extracted methane, temporarily limits coal royalties to 7 percent through September 2034, and increases Alaska’s share of certain leasing revenue.</li><li>The title accelerates pending coal leases, makes at least 4 million additional federal acres available for coal leasing, authorizes specified federal coal mining, and requires rising timber sales and long-term timber contracts through 2034.</li><li>Wind and solar projects on federal land must pay acreage rent before generation and annual capacity fees afterward, while 25 percent of covered project revenue goes to the host state and 25 percent goes to affected counties beginning in 2026.</li><li>The title provides funding for Strategic Petroleum Reserve repairs and petroleum purchases, energy and critical-mineral financing, Energy Department artificial intelligence work, water conveyance and storage improvements, and the nation’s 250th anniversary, while canceling unobligated funds from several earlier programs.</li></ul><h3 id="title-vi-committee-on-environment-and-public-works" tabindex="-1">TITLE VI, COMMITTEE ON ENVIRONMENT AND PUBLIC WORKS <a class="header-anchor" href="#title-vi-committee-on-environment-and-public-works" aria-label="Permalink to &quot;TITLE VI, COMMITTEE ON ENVIRONMENT AND PUBLIC WORKS&quot;">​</a></h3><p>This title cancels unobligated funding for a wide range of environmental, climate, clean transportation, federal building, and environmental review programs, and it repeals the Greenhouse Gas Reduction Fund. It provides $256.657 million for repairs, restoration, maintenance, and security at the John F. Kennedy Center for the Performing Arts. It also creates an optional fee process under which project sponsors can pay for expedited environmental assessments or environmental impact statements.</p><p><strong>Key takeaways:</strong></p><ul><li>Unobligated funding is canceled for programs involving clean heavy-duty vehicles, diesel emissions, air pollution, low-emissions electricity, methane reduction, greenhouse gas planning and reporting, environmental justice, climate data, and endangered species recovery plans.</li><li>The Greenhouse Gas Reduction Fund is repealed, and its remaining unobligated funding is canceled.</li><li>Unobligated funding is also canceled for neighborhood access and equity grants, low-carbon construction and transportation materials, federal building assistance, sustainable federal technologies, and environmental review implementation.</li><li>The title changes a date in the methane emissions program from calendar year 2024 to calendar year 2034.</li><li>The Kennedy Center receives $256.657 million, available through September 30, 2029, with no more than 3 percent allowed for administrative costs.</li><li>Project sponsors may pay 125 percent of anticipated preparation or supervision costs to obtain deadlines of 180 days for an environmental assessment and one year after the notice of intent for an environmental impact statement.</li></ul><h3 id="title-vii-finance-part-1-of-5" tabindex="-1">TITLE VII, FINANCE (part 1 of 5) <a class="header-anchor" href="#title-vii-finance-part-1-of-5" aria-label="Permalink to &quot;TITLE VII, FINANCE (part 1 of 5)&quot;">​</a></h3><p>This part of Title VII makes many individual and small-business tax provisions permanent or more generous, including lower tax rates, the larger standard deduction, the child tax credit, the qualified business income deduction, and estate and gift tax exemptions. It also changes deductions for state and local taxes, mortgage interest, disaster losses, educator and moving expenses, gambling losses, and several other items. New temporary deductions cover qualifying tips, overtime pay, and interest on certain U.S.-assembled vehicle loans, while new tax-advantaged “Trump accounts” allow savings for children and include a federal contribution pilot program.</p><p><strong>Key takeaways:</strong></p><ul><li>The title permanently extends lower individual tax rates and the increased standard deduction, raises the child tax credit to $2,200, and generally continues the elimination of personal exemptions.</li><li>Taxpayers age 65 or older may claim a temporary $6,000 deduction through 2028, subject to income limits, Social Security number requirements, and joint-filing rules for married taxpayers.</li><li>The state and local tax deduction cap rises to $40,000 for 2025, increases through 2029, phases down for higher-income taxpayers, and returns to $10,000 after 2029.</li><li>For 2025 through 2028, eligible taxpayers may deduct up to $25,000 of qualifying tips, qualifying overtime premiums up to $12,500 per person, and up to $10,000 of interest on qualifying new U.S.-assembled passenger vehicle loans, with income-based reductions and reporting requirements.</li><li>The title expands or extends tax treatment for small-business income, ABLE accounts, certain disaster losses, intelligence-community moving expenses, student loans discharged because of death or permanent disability, and hazardous-duty service in specified countries.</li><li>The title creates tax-advantaged Trump accounts for minors, generally caps ordinary annual contributions at $5,000 before age 18, permits certain employer and charitable contributions, and provides a $1,000 federal contribution for eligible U.S.-citizen children born from 2025 through 2028.</li></ul><h3 id="title-vii-finance-part-2-of-5" tabindex="-1">TITLE VII, FINANCE (part 2 of 5) <a class="header-anchor" href="#title-vii-finance-part-2-of-5" aria-label="Permalink to &quot;TITLE VII, FINANCE (part 2 of 5)&quot;">​</a></h3><p>This title makes broad changes to business taxation intended to encourage domestic investment, research, manufacturing, and employee benefits. It permanently allows immediate deductions for many business assets and domestic research costs, creates or expands incentives for production facilities, semiconductor manufacturing, paid leave, and spaceports, and adjusts limits on interest and other deductions. It also revises international tax rules governing foreign income, foreign tax credits, controlled foreign corporations, and payments that erode the U.S. tax base.</p><p><strong>Key takeaways:</strong></p><ul><li>Businesses may permanently deduct 100 percent of the cost of qualifying property acquired after January 19, 2025, with a temporary option to use lower percentages for the first tax year ending after that date.</li><li>Domestic research and software-development costs generally become immediately deductible for tax years beginning after 2024, while foreign research costs continue to be deducted over 15 years and transition rules allow certain earlier domestic costs to be recovered faster.</li><li>The title raises the immediate-expensing limit for certain business assets to $2.5 million, creates a 100 percent deduction for qualifying U.S. production property, and increases the advanced manufacturing investment credit from 25 percent to 35 percent.</li><li>The paid family and medical leave credit becomes permanent and may be based on qualifying wages or insurance premiums, while new meal-deduction exceptions apply to certain fishing vessels and remote fish-processing facilities.</li><li>Spaceports become eligible for the same type of tax-exempt facility bond financing available to airports, including qualifying manufacturing, launch, reentry, flight-control, and cargo facilities.</li><li>International provisions revise deductions and foreign tax credits for foreign income, increase the base erosion minimum tax rate to 10.5 percent, permanently extend the related-controlled-foreign-corporation look-through rule, and update ownership and income-allocation rules for foreign corporations.</li></ul><h3 id="title-vii-finance-part-3-of-5" tabindex="-1">TITLE VII, FINANCE (part 3 of 5) <a class="header-anchor" href="#title-vii-finance-part-3-of-5" aria-label="Permalink to &quot;TITLE VII, FINANCE (part 3 of 5)&quot;">​</a></h3><p>This title makes broad, mostly permanent tax changes for families, education, community development, charitable giving, small businesses, rural areas, and certain tax-exempt institutions. It expands tax benefits for child care, adoption, education, housing, investment in disadvantaged communities, small-business stock, farming, and rural lending, while increasing some taxes or limits on wealthy colleges, tax-exempt organizations, and charitable deductions. Most provisions take effect between 2025 and 2027, although some begin upon enactment.</p><p><strong>Key takeaways:</strong></p><ul><li>Families receive larger employer child care incentives, a partly refundable adoption credit, recognition of tribal special-needs determinations, a higher dependent-care assistance limit, and an expanded child and dependent care credit.</li><li>Education changes create a federal credit of up to $1,700 for contributions to approved scholarship organizations in participating states, make qualifying scholarships tax-free, permanently allow tax-free employer student-loan payments, and expand eligible uses of 529 accounts.</li><li>The title raises the investment-income tax on certain private colleges and universities based on endowment size and expands the tax on high compensation to cover all current and former employees of affected tax-exempt organizations.</li><li>Community development provisions renew Opportunity Zones on a 10-year cycle with new eligibility, rural incentives, reporting, and public outcome data, while permanently expanding low-income housing and New Markets tax credits.</li><li>Charitable-giving rules provide a permanent deduction of up to $1,000, or $2,000 for joint filers, for nonitemizers, but generally allow individual deductions only above 0.5 percent of income and corporate deductions only above 1 percent of taxable income.</li><li>Small-business and rural provisions expand the tax exclusion for qualified small-business stock, restore the $20,000-and-200-transaction reporting threshold for third-party payment networks, raise other payment-reporting thresholds, provide tax benefits for sound recordings and rural loans, reduce federal firearm transfer and making taxes for certain devices to zero, and allow installment tax payments on qualifying farmland sales.</li></ul><h3 id="title-vii-finance-part-4-of-5" tabindex="-1">TITLE VII, FINANCE (part 4 of 5) <a class="header-anchor" href="#title-vii-finance-part-4-of-5" aria-label="Permalink to &quot;TITLE VII, FINANCE (part 4 of 5)&quot;">​</a></h3><p>This title ends or accelerates the expiration of many clean-energy tax benefits, including credits for clean vehicles, home and building efficiency, hydrogen, wind, solar, and advanced manufacturing. It restricts energy tax benefits involving certain foreign-controlled or foreign-influenced entities while extending or expanding selected benefits for clean fuels, carbon capture, nuclear power, fossil-fuel development, and other energy activities. It also changes customs and business tax rules, creates a 1 percent tax on certain cash-funded remittance transfers, strengthens enforcement of employee retention credit claims, and adds identification requirements for education tax credits. Finally, it funds a Treasury report on replacing the IRS Direct File program with public-private free-filing options.</p><p><strong>Key takeaways:</strong></p><ul><li>Clean vehicle credits generally end for vehicles acquired after September 30, 2025, while several home, building, refueling, hydrogen, wind, solar, and manufacturing incentives end or phase out between 2025 and 2034.</li><li>Nuclear, clean electricity, manufacturing, clean fuel, and carbon-capture credits are denied or restricted when taxpayers, projects, components, or contractual arrangements involve defined prohibited foreign entities.</li><li>The clean fuel production credit is extended through 2029, limited mainly to feedstocks from the United States, Mexico, or Canada, and revised to prevent duplicate credits and change emissions calculations.</li><li>The title makes the limit on excess business losses permanent, changes taxation of partnership payments and executive compensation, and creates a 1 percent tax on remittances funded with cash or similar physical instruments after 2025.</li><li>Customs violations involving low-value imports face added civil penalties, and the commercial low-value shipment exception is repealed beginning July 1, 2027.</li><li>The title limits new employee retention credit claims, expands enforcement and penalties, requires Social Security numbers for education credits, and provides $15 million for a report on replacing IRS Direct File.</li></ul><h3 id="title-vii-finance-part-5-of-5" tabindex="-1">TITLE VII, FINANCE (part 5 of 5) <a class="header-anchor" href="#title-vii-finance-part-5-of-5" aria-label="Permalink to &quot;TITLE VII, FINANCE (part 5 of 5)&quot;">​</a></h3><p>This title makes broad changes to Medicaid, Medicare, health insurance tax credits, health savings accounts, and rural health funding. It tightens eligibility and verification rules, adds Medicaid work or community-engagement requirements and cost sharing for certain adults, restricts several financing practices, and pauses selected federal enrollment and nursing-home staffing rules through September 2034. It also increases the federal debt limit by $5 trillion and bars federally funded unemployment benefits for people whose base-period wages reach $1 million.</p><p><strong>Key takeaways:</strong></p><ul><li>States must strengthen Medicaid enrollment checks, including identifying people enrolled in multiple states, regularly checking addresses and death records, conducting more frequent eligibility reviews for certain adults, and screening providers against death records.</li><li>Beginning in 2027, many adults covered through Medicaid expansion must generally document at least 80 hours per month of work, community service, work-program participation, or qualifying education, subject to listed exclusions and hardship rules.</li><li>The title narrows federal health coverage and premium tax credit eligibility based on immigration status, strengthens Marketplace verification, requires repayment of excess advance premium tax credits without the prior cap, and reduces federal reimbursement for emergency Medicaid in expansion states.</li><li>The title limits Medicaid provider taxes and state-directed payments, requires federal budget neutrality for Medicaid demonstration projects, shortens retroactive coverage periods, and temporarily blocks Medicaid payments to certain nonprofit reproductive health providers that perform abortions outside specified exceptions.</li><li>The title expands some patient options by supporting additional home- and community-based services, making telehealth deductible relief permanent, allowing bronze and catastrophic plans to qualify for health savings accounts, and permitting health savings account funds for qualifying direct primary care arrangements.</li><li>The title creates a $50 billion rural health transformation program for fiscal years 2026 through 2030, raises the federal debt limit by $5 trillion, and ends federally funded unemployment payments to people with at least $1 million in base-period wages.</li></ul><h3 id="title-viii-committee-on-health-education-labor-and-pensions" tabindex="-1">TITLE VIII, COMMITTEE ON HEALTH, EDUCATION, LABOR, AND PENSIONS <a class="header-anchor" href="#title-viii-committee-on-health-education-labor-and-pensions" aria-label="Permalink to &quot;TITLE VIII, COMMITTEE ON HEALTH, EDUCATION, LABOR, AND PENSIONS&quot;">​</a></h3><p>This title makes broad changes to federal student aid beginning mainly in 2026, including how family assets affect aid, student and parent loan limits, repayment plans, Pell Grants, and program accountability. It also funds student-loan administration, a national heroes statue project, and stronger screening of potential sponsors for unaccompanied migrant children, while temporarily restoring earlier rules for borrower-defense and closed-school loan discharges.</p><p><strong>Key takeaways:</strong></p><ul><li>Starting July 1, 2026, financial-aid calculations exclude a family’s primary farm, a family-controlled business with no more than 100 employees, and a family-controlled commercial fishing business and related assets.</li><li>For instruction beginning on or after July 1, 2026, graduate and professional students may no longer receive federal PLUS loans, new annual and lifetime borrowing limits apply to students and parents, and some students already enrolled may temporarily remain under prior rules.</li><li>The title creates a new income-based Repayment Assistance Plan, narrows repayment choices for new loans, ends existing income-contingent repayment plans in 2028, limits some deferments and forbearances for newer loans, and allows borrowers to rehabilitate defaulted loans twice.</li><li>Beginning in the 2026–2027 award year, Pell Grant rules account for foreign income, exclude students with high student aid indexes or enough nonfederal grant aid to cover attendance costs, and create Workforce Pell Grants for qualifying short-term training programs.</li><li>Starting July 1, 2026, college programs whose graduates repeatedly earn less than specified working-adult benchmarks may lose access to federal Direct Loan funds after notice and an opportunity to appeal.</li><li>The title provides $1 billion for federal student-loan administration, $40 million for statues for the National Garden of American Heroes, and $300 million for screening sponsors and protecting unaccompanied migrant children, and it restores earlier borrower-defense and closed-school discharge rules for loans first issued before July 1, 2035.</li></ul><h3 id="title-ix-committee-on-homeland-security-and-governmental-affairs" tabindex="-1">TITLE IX, COMMITTEE ON HOMELAND SECURITY AND GOVERNMENTAL AFFAIRS <a class="header-anchor" href="#title-ix-committee-on-homeland-security-and-governmental-affairs" aria-label="Permalink to &quot;TITLE IX, COMMITTEE ON HOMELAND SECURITY AND GOVERNMENTAL AFFAIRS&quot;">​</a></h3><p>This title provides major new funding for border barriers, Customs and Border Protection personnel and facilities, immigration detention, border technology, and state and local security efforts. It also strengthens eligibility checks for federal employee health benefits, funds pandemic spending oversight, and supports efforts to improve executive branch budgeting and accounting.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides $46.55 billion for border barriers, access roads, surveillance equipment, and related construction and ground preparation through September 2029.</li><li>It provides more than $12 billion for additional Customs and Border Protection personnel, bonuses, vehicles, and facilities, while barring funding for processing coordinator recruitment, hiring, or training after October 31, 2028.</li><li>It provides $45 billion for detention of single adults and families during immigration proceedings and, when removal is ordered, until removal occurs.</li><li>It provides about $6.17 billion for border screening, surveillance, air and marine capabilities, biometric systems, and efforts to stop narcotics, while limiting funding for untested autonomous surveillance towers.</li><li>It funds state and local security activities, including drone-threat detection, the 2026 FIFA World Cup, the 2028 Olympics, Operation Stonegarden, border-related projects, presidential residence protection, and reimbursement for support of the Department of Homeland Security&#39;s border mission.</li><li>It requires stronger verification and audits of family-member eligibility for federal employee health coverage, provides $88 million for pandemic spending oversight through 2034, and gives the Office of Management and Budget $100 million to identify budget and accounting efficiencies.</li></ul><h3 id="title-x-committee-on-the-judiciary" tabindex="-1">TITLE X, COMMITTEE ON THE JUDICIARY <a class="header-anchor" href="#title-x-committee-on-the-judiciary" aria-label="Permalink to &quot;TITLE X, COMMITTEE ON THE JUDICIARY&quot;">​</a></h3><p>This title creates and increases numerous immigration-related fees, generally starting in fiscal year 2025 and rising with inflation, while directing the proceeds to immigration agencies or the Treasury. It also provides major funding through 2029 for immigration enforcement, removals, law enforcement staffing and training, prisons, the Secret Service, and Justice Department activities. In addition, it funds federal court reporting and training and extends and expands compensation for people exposed to radiation from nuclear testing, uranium work, and Manhattan Project waste.</p><p><strong>Key takeaways:</strong></p><ul><li>New or increased fees apply to asylum applications, employment authorization, parole, temporary protected status, nonimmigrant visas, travel records, immigration court filings and appeals, certain arrests, and apprehensions between ports of entry.</li><li>Most immigration fees cannot be waived or reduced, generally increase with inflation after fiscal year 2025, and are deposited in whole or in part into the Treasury or immigration agency accounts.</li><li>The title provides $2.055 billion for broader Department of Homeland Security immigration activities and $29.85 billion for Immigration and Customs Enforcement staffing, transportation, facilities, technology, detention, and removal operations.</li><li>It provides additional funding for federal law enforcement training, the Justice Department, state and local immigration-related enforcement costs, the Bureau of Prisons, and the Secret Service.</li><li>It funds federal court data collection concerning orders that grant relief to people who are not parties to cases against the federal government and funds judicial training concerning such claims.</li><li>It extends the Radiation Exposure Compensation Fund through December 31, 2028, expands eligibility for nuclear testing and uranium-related claims, and creates compensation for qualifying exposure to Manhattan Project waste in specified areas.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ21.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ21.xml</a></p>',68))]))}});export{h as __pageData,g as default};
